1043	  async abrirCaixa(restaurantId: number, body: { nome_operador: string; valor_inicial?: number }) {
1044	    if (!body.nome_operador?.trim()) throw new BadRequestException('Nome do operador é obrigatório');
1045	
1046	    const { data: existente } = await this.supabase.client
1047	      .from('caixas').select('id, status').eq('restaurant_id', restaurantId)
1048	      .in('status', ['aberto', 'expirado']).maybeSingle();
1049	
1050	    if (existente?.status === 'aberto') throw new ConflictException('Já existe um caixa aberto');
1051	    if (existente?.status === 'expirado') throw new ConflictException('Existe um caixa expirado. Feche-o antes de abrir outro');
1052	
1053	    // Usar saldo_caixa como valor_inicial padrão se não informado
1054	    const { data: restaurant } = await this.supabase.client
1055	      .from('restaurants').select('saldo_caixa').eq('id', restaurantId).maybeSingle();
1056	    const saldoCaixaAtual = restaurant?.saldo_caixa ?? 0;
1057	    const valorInicial = body.valor_inicial !== undefined ? body.valor_inicial : saldoCaixaAtual;
1058	
1059	    const { data: novo, error } = await this.supabase.client
1060	      .from('caixas')
1061	      .insert({ restaurant_id: restaurantId, nome_operador: body.nome_operador.trim(), valor_inicial: valorInicial })
1062	      .select('*')
1063	      .single();
1064	
1065	    if (error) throw error;
1066	
1067	    // Zerar saldo_caixa — o valor agora está dentro do caixa aberto
1068	    await this.supabase.client.from('restaurants')
1069	      .update({ saldo_caixa: 0 }).eq('id', restaurantId);
1070	
1071	    return this.getCaixa(restaurantId);
1072	  }
1073	
1074	  async fecharCaixa(restaurantId: number, body?: { dinheiro_contado?: number }) {
1075	    const { data: caixa } = await this.supabase.client
1076	      .from('caixas').select('*').eq('restaurant_id', restaurantId)
1077	      .in('status', ['aberto', 'expirado']).maybeSingle();
1078	
1079	    if (!caixa) throw new NotFoundException('Nenhum caixa aberto');
1080	
1081	    const { data: pedidosAbertos } = await this.supabase.client
1082	      .from('orders').select('id, status, total')
1083	      .eq('caixa_id', caixa.id)
1084	      .in('status', this.STATUS_ABERTOS);
1085	
1086	    const { data: comandasAbertas } = await this.supabase.client
1087	      .from('orders')
1088	      .select('id, status, mesa_id, mesas(numero, nome)')
1089	      .eq('caixa_id', caixa.id)
1090	      .eq('canal', 'presencial')
1091	      .in('status', this.COMANDA_STATUS_ABERTOS);
1092	
1093	    const { data: mesasAbertas } = await this.supabase.client
1094	      .from('mesas')
1095	      .select('id, numero, nome, status')
1096	      .eq('restaurant_id', restaurantId)
