// Comanda/pedido pendente (fiado) cujo caixa original já fechou: realoca pro caixa
// que estiver aberto no momento do pagamento (principal, se houver mais de um).
async garantirCaixaAbertoParaLancamento(restaurantId: number, caixaIdAtual: number | null): Promise<number | null> {
  if (caixaIdAtual) {
    const { data: caixaAtual } = await this.supabase.client
      .from('caixas').select('id, status').eq('id', caixaIdAtual).maybeSingle();
    if (caixaAtual?.status === 'aberto') return caixaIdAtual;
  }

  const { data: principal } = await this.supabase.client
    .from('caixas').select('id').eq('restaurant_id', restaurantId)
    .eq('status', 'aberto').eq('is_principal', true).maybeSingle();
  if (principal) return principal.id;

  const { data: qualquerAberto } = await this.supabase.client
    .from('caixas').select('id').eq('restaurant_id', restaurantId)
    .eq('status', 'aberto').order('aberto_em', { ascending: true }).maybeSingle();
  return qualquerAberto?.id ?? null;
}

