14	  private gerarToken(garcomId: number): string {
15	    const secret = this.config.getOrThrow('GARCOM_JWT_SECRET');
16	    return jwt.sign({ garcomId }, secret, { expiresIn: '12h' });
17	  }
18	
19	  async login(loginKey: string, password: string) {
20	    if (!loginKey || !password) throw new BadRequestException('Informe usuário e senha');
21	
22	    const { data: garcom } = await this.supabase.client
23	      .from('garcons')
24	      .select('id, password_hash, ativo, restaurants(aparencia)')
25	      .eq('login_key', loginKey)
26	      .maybeSingle();
27	
28	    if (!garcom?.password_hash) throw new UnauthorizedException('Credenciais inválidas');
29	    if (!garcom.ativo) throw new UnauthorizedException('Acesso desativado');
30	
31	    const ok = await bcrypt.compare(password, garcom.password_hash);
32	    if (!ok) throw new UnauthorizedException('Credenciais inválidas');
33	
34	    const restauranteAberto = (garcom as any).restaurants?.aparencia?.aberto === true;
