1	import { Body, Controller, Delete, Get, Param, ParseIntPipe, Patch, Post, Req, UseGuards } from '@nestjs/common';
2	import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
3	import { GarconsService } from './garcons.service';
4	import type { AtualizarGarcomBody, ComissaoConfigBody, CriarGarcomBody } from './garcons.service';
5	
6	@Controller('restaurante/garcons')
7	@UseGuards(RestaurantOwnerGuard)
8	export class RestauranteGarconsController {
9	  constructor(private service: GarconsService) {}
10	
11	  @Get()
12	  listar(@Req() req: any) {
13	    return this.service.listar(req.restaurantId);
14	  }
15	
16	  @Get('online')
17	  online(@Req() req: any) {
18	    return this.service.garconsOnline(req.restaurantId);
19	  }
20	
21	  @Post()
22	  criar(@Body() body: CriarGarcomBody, @Req() req: any) {
23	    return this.service.criar(req.restaurantId, body);
24	  }
25	
26	  @Patch(':id')
27	  atualizar(@Param('id', ParseIntPipe) id: number, @Body() body: AtualizarGarcomBody, @Req() req: any) {
28	    return this.service.atualizar(id, req.restaurantId, body);
29	  }
30	
