1	import { apiPath } from '../lib/apiUrl';
2	
3	const API = apiPath('/api/garcom');
4	const TOKEN_KEY = 'garcom_access_token';
5	
6	export const getGarcomToken = () => localStorage.getItem(TOKEN_KEY);
7	export const setGarcomToken = (token) => localStorage.setItem(TOKEN_KEY, token);
8	export const clearGarcomToken = () => localStorage.removeItem(TOKEN_KEY);
9	
10	async function garcomFetch(path, options = {}) {
11	  const token = getGarcomToken();
12	  if (!token) throw new Error('Sessão expirada. Faça login novamente.');
13	
14	  const res = await fetch(`${API}${path}`, {
15	    ...options,
16	    headers: {
17	      'Content-Type': 'application/json',
18	      'x-garcom-token': token,
19	      ...options.headers,
20	    },
21	  });
22	
23	  const contentType = res.headers.get('content-type') ?? '';
24	  const isJson = contentType.includes('application/json');
25	
26	  if (!res.ok) {
27	    if (res.status === 401) clearGarcomToken();
28	    const err = isJson ? await res.json().catch(() => ({})) : {};
29	    throw new Error(err?.message ?? `HTTP ${res.status}`);
30	  }
31	
32	  return isJson ? res.json() : {};
33	}
34	
35	export const login = async (loginKey, password) => {
36	  const res = await fetch(`${API}/auth/login`, {
37	    method: 'POST',
38	    headers: { 'Content-Type': 'application/json' },
39	    body: JSON.stringify({ login_key: loginKey, password }),
40	  });
41	  const contentType = res.headers.get('content-type') ?? '';
42	  const isJson = contentType.includes('application/json');
43	  const data = isJson ? await res.json().catch(() => ({})) : {};
44	  if (!res.ok) throw new Error(data?.message ?? `HTTP ${res.status}`);
45	  return data;
46	};
47	
48	export const getMe = () => garcomFetch('/me');
49	export const getMesas = () => garcomFetch('/mesas');
50	export const getCaixasAbertos = () => garcomFetch('/caixas-abertos');
51	export const getProdutos = () => garcomFetch('/produtos');
52	export const getMinhasComandas = () => garcomFetch('/comandas');
53	export const getItensProntos = () => garcomFetch('/itens-prontos');
54	export const getComanda = (id) => garcomFetch(`/comandas/${id}`);
55	
56	export const abrirComanda = ({ mesa_id, cliente_nome, cliente_telefone, caixa_id }) =>
57	  garcomFetch('/comandas/abrir', {
58	    method: 'POST',
59	    body: JSON.stringify({ mesa_id: mesa_id ?? null, cliente_nome, cliente_telefone, caixa_id }),
60	  });
61	
62	export const adicionarItens = (comandaId, itens) =>
63	  garcomFetch(`/comandas/${comandaId}/itens`, { method: 'POST', body: JSON.stringify({ itens }) });
64	
65	export const editarItem = (comandaId, itemId, body) =>
66	  garcomFetch(`/comandas/${comandaId}/itens/${itemId}`, { method: 'PATCH', body: JSON.stringify(body) });
67	
68	export const removerItem = (comandaId, itemId) =>
69	  garcomFetch(`/comandas/${comandaId}/itens/${itemId}`, { method: 'DELETE' });
70	
71	export const editarClienteComanda = (comandaId, cliente_nome, cliente_telefone) =>
72	  garcomFetch(`/comandas/${comandaId}/cliente`, { method: 'PATCH', body: JSON.stringify({ cliente_nome, cliente_telefone }) });
73	
74	export const excluirComanda = (comandaId) =>
75	  garcomFetch(`/comandas/${comandaId}`, { method: 'DELETE' });
76	
77	export const registrarPagamento = (comandaId, valor, forma_pagamento, valor_recebido) =>
78	  garcomFetch(`/comandas/${comandaId}/pagamento`, { method: 'POST', body: JSON.stringify({ valor, forma_pagamento, valor_recebido }) });
79	
80	export const enviarItens = (comandaId) =>
81	  garcomFetch(`/comandas/${comandaId}/enviar`, { method: 'POST' });
82	
83	export const fecharComanda = (comandaId, formaPagamento) =>
