        {/* Acompanhamento público da mesa via QR — sem login */}
        <Route path="/mesa/acompanhar/:token" element={<MesaAcompanhar />} />

        <Route path="*" element={<NotFound />} />
      </RouterRoutes>
      </ErrorBoundary>
    </BrowserRouter>
  );
};

export default Routes;

