async atualizarCaixa(restaurantId: number, caixaId: number, body: { nome?: string; nome_operador?: string; valor_inicial?: number }) {
  const { data: caixa } = await this.supabase.client
    .from('caixas').select('id, status').eq('id', caixaId).eq('restaurant_id', restaurantId).maybeSingle();
  if (!caixa) throw new NotFoundException('Caixa não encontrado');
  if (caixa.status !== 'aberto') throw new BadRequestException('Só é possível editar um caixa aberto');

  const update: Record<string, unknown> = {};
  if (body.nome !== undefined) {
    if (!body.nome.trim()) throw new BadRequestException('Nome do caixa não pode ficar vazio');
    update.nome = body.nome.trim();
  }
  if (body.nome_operador !== undefined) {
    if (!body.nome_operador.trim()) throw new BadRequestException('Nome do operador não pode ficar vazio');
    update.nome_operador = body.nome_operador.trim();
  }
  if (body.valor_inicial !== undefined) update.valor_inicial = body.valor_inicial;

  const { data, error } = await this.supabase.client
    .from('caixas').update(update).eq('id', caixaId).select('*').single();
  if (error) throw error;
  return data;
}

async reabrirCaixa(restaurantId: number, caixaId: number) {
  const { data: caixa } = await this.supabase.client
    .from('caixas').select('id, status, nome').eq('id', caixaId).eq('restaurant_id', restaurantId).maybeSingle();
  if (!caixa) throw new NotFoundException('Caixa não encontrado');
  if (caixa.status === 'aberto') throw new BadRequestException('Esse caixa já está aberto');

  const { data: outroAberto } = await this.supabase.client
    .from('caixas').select('id').eq('restaurant_id', restaurantId).eq('nome', caixa.nome).eq('status', 'aberto').maybeSingle();
  if (outroAberto) throw new ConflictException(`Já existe um caixa "${caixa.nome}" aberto`);

  const { data, error } = await this.supabase.client
    .from('caixas')
    .update({ status: 'aberto', fechado_em: null, fechado_com_pendencias: false, pendencias_fechamento: null, destinacao_fechamento: null })
    .eq('id', caixaId)
    .select('*').single();
  if (error) throw error;
  return data;
}

