import React, { useState, useEffect, useCallback } from 'react';
import { getCaixasAbertos, abrirCaixa, fecharCaixa, atualizarCaixa, listarColaboradores } from '../../services/restauranteService';
import Icon from '../../components/AppIcon';

const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);

const CaixaCard = ({ caixa, colaborador, onFechar, onMudou }) => {
  const [editando, setEditando] = useState(false);
  const [nome, setNome] = useState(caixa.nome);
  const [nomeOperador, setNomeOperador] = useState(caixa.nome_operador);
  const [valorInicial, setValorInicial] = useState(caixa.valor_inicial);
  const [erro, setErro] = useState(null);
  const [salvando, setSalvando] = useState(false);
  const [copiado, setCopiado] = useState(false);

  const salvar = async () => {
    setErro(null);
    setSalvando(true);
    try {
      await atualizarCaixa(caixa.id, { nome: nome.trim(), nome_operador: nomeOperador.trim(), valor_inicial: parseFloat(valorInicial) || 0 });
      setEditando(false);
      onMudou();
    } catch (e) { setErro(e.message); } finally { setSalvando(false); }
  };

  const linkColaborador = colaborador ? `${window.location.origin}/colaborador/${colaborador.login_key}` : null;
  const copiarLink = () => {
    navigator.clipboard?.writeText(linkColaborador);
    setCopiado(true);
    setTimeout(() => setCopiado(false), 2000);
  };

  if (editando) {
    return (
      <div className="p-3 bg-[#FAFAFA] rounded-xl space-y-2">
        <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Nome do caixa"
          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
        <input value={nomeOperador} onChange={(e) => setNomeOperador(e.target.value)} placeholder="Nome do operador"
          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
        <input type="number" min="0" step="0.01" value={valorInicial} onChange={(e) => setValorInicial(e.target.value)} placeholder="Valor inicial"
          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
        {erro && <p className="text-xs text-red-600">{erro}</p>}
        <div className="flex gap-2">
          <button onClick={() => setEditando(false)} className="flex-1 py-1.5 text-xs border border-[#E4E4E7] rounded-lg text-[#71717A]">Cancelar</button>
          <button onClick={salvar} disabled={salvando} className="flex-1 py-1.5 text-xs font-bold bg-[#FF441F] text-white rounded-lg disabled:opacity-50">
            {salvando ? 'Salvando...' : 'Salvar'}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="p-3 bg-[#FAFAFA] rounded-xl">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm font-bold text-[#18181B]">{caixa.nome}</p>
          <p className="text-xs text-[#71717A]">{caixa.nome_operador} · {fmt(caixa.resumo?.total_vendas)} em vendas</p>
        </div>
        <div className="flex gap-1.5">
          <button onClick={() => setEditando(true)} className="px-2.5 py-1.5 text-xs font-medium border border-[#E4E4E7] rounded-lg text-[#71717A] hover:bg-[#F4F4F5]">
            Editar
          </button>
          <button onClick={onFechar} className="px-3 py-1.5 text-xs font-bold bg-red-500 text-white rounded-lg hover:bg-red-600">
            Fechar
          </button>
        </div>
      </div>
      {linkColaborador && (
        <div className="flex items-center gap-2 mt-2 bg-white rounded-lg px-2.5 py-1.5 border border-[#E4E4E7]">
          <span className="text-[10px] text-[#71717A]">Colaborador: {colaborador.nome}</span>
          <span className="text-[10px] font-mono text-[#A1A1AA] truncate flex-1">{linkColaborador}</span>
          <button onClick={copiarLink} className="text-[10px] font-bold text-[#FF441F] flex-shrink-0">{copiado ? 'Copiado!' : 'Copiar'}</button>
        </div>
      )}
    </div>
  );
};

// Caixas secundários (Bar, Salão...) além do Principal — que já tem seu próprio card
// acima. Permite abrir mais um ponto de venda simultâneo, editar e fechar cada um sozinho.
const OutrosCaixasPanel = () => {
  const [caixas, setCaixas] = useState([]);
  const [colaboradores, setColaboradores] = useState([]);
  const [mostrarForm, setMostrarForm] = useState(false);
  const [nomeOperador, setNomeOperador] = useState('');
  const [nome, setNome] = useState('');
  const [valorInicial, setValorInicial] = useState('');
  const [erro, setErro] = useState(null);
  const [salvando, setSalvando] = useState(false);

  const carregar = useCallback(() => {
    getCaixasAbertos().then((lista) => setCaixas(lista.filter((c) => !c.is_principal))).catch(() => {});
    listarColaboradores().then(setColaboradores).catch(() => {});
  }, []);

  useEffect(() => { carregar(); }, [carregar]);

  const handleAbrir = async () => {
    if (!nomeOperador.trim() || !nome.trim()) { setErro('Informe o nome do operador e o nome do caixa (ex: Bar)'); return; }
    setErro(null);
    setSalvando(true);
    try {
      await abrirCaixa({ nome_operador: nomeOperador.trim(), nome: nome.trim(), valor_inicial: parseFloat(valorInicial) || 0, is_principal: false });
      setNomeOperador(''); setNome(''); setValorInicial(''); setMostrarForm(false);
      carregar();
    } catch (e) { setErro(e.message); } finally { setSalvando(false); }
  };

  const handleFechar = async (caixa) => {
    const dinheiro = caixa.resumo?.especie_calculada ?? 0;
    let permitir_pendencias = false;
    try {
      await fecharCaixa({ caixa_id: caixa.id, dinheiro_contado: dinheiro });
    } catch (e) {
      if (e.data?.pedidos || e.data?.comandas || e.data?.mesas) {
        const total = (e.data.pedidos_abertos ?? 0) + (e.data.comandas_abertas ?? 0) + (e.data.mesas_abertas ?? 0);
        if (!window.confirm(`Este caixa tem ${total} pendência(s) em aberto. Fechar mesmo assim e deixar pendente (fiado)?`)) return;
        permitir_pendencias = true;
      } else {
        alert(e.message);
        return;
      }
    }
    if (permitir_pendencias) {
      try { await fecharCaixa({ caixa_id: caixa.id, dinheiro_contado: dinheiro, permitir_pendencias: true }); } catch (e) { alert(e.message); return; }
    }
    carregar();
  };

  return (
    <div className="bg-white rounded-2xl border border-[#E4E4E7] p-5 mt-4">
      <div className="flex items-center gap-2 mb-4">
        <Icon name="Layers" size={18} className="text-[#FF441F]" />
        <h2 className="font-bold text-[#18181B]">Outros caixas</h2>
        <button onClick={() => setMostrarForm((v) => !v)}
          className="ml-auto text-xs font-bold text-[#FF441F] hover:underline">
          {mostrarForm ? 'Cancelar' : '+ Abrir caixa'}
        </button>
      </div>

      {mostrarForm && (
        <div className="space-y-2 mb-4 p-3 bg-[#FAFAFA] rounded-xl">
          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Nome do caixa (ex: Bar, Salão)"
            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
          <input value={nomeOperador} onChange={(e) => setNomeOperador(e.target.value)} placeholder="Nome do operador"
            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
          <input type="number" min="0" step="0.01" value={valorInicial} onChange={(e) => setValorInicial(e.target.value)}
            placeholder="Valor inicial (R$)"
            className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-[#FF441F]" />
          {erro && <p className="text-xs text-red-600">{erro}</p>}
          <button onClick={handleAbrir} disabled={salvando}
            className="w-full py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19] disabled:opacity-50">
            {salvando ? 'Abrindo...' : 'Abrir caixa'}
          </button>
        </div>
      )}

      {caixas.length === 0 ? (
        <p className="text-xs text-[#A1A1AA]">Nenhum outro caixa aberto além do Principal.</p>
      ) : (
        <div className="space-y-2">
          {caixas.map((c) => (
            <CaixaCard
              key={c.id}
              caixa={c}
              colaborador={colaboradores.find((col) => col.setor === c.nome)}
              onFechar={() => handleFechar(c)}
              onMudou={carregar}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default OutrosCaixasPanel;

